python3 -c $'import sys,json,math\nA="<>+-.,[]";c=4448070169\ndef D(n):\n if n<1:raise ValueError\n b=[]\n while n>1:\n  n,r=divmod(n,257)\n  if not r:raise ValueError\n  b[:0]=[r-1]\n return bytes(b)\ndef G(b):\n n=1\n for v in b:n=n*257+v+1\n return n\ndef N(n):\n s=""\n while n:n,r=divmod(n-1,8);s=A[r]+s\n return s\ndef W(s):\n v=s.replace("AG","0").replace("TC","1")\n if len(v)*2!=len(s)or len(v)%8:raise ValueError\n return bytes(int(v[i:i+8],2)for i in range(0,len(v),8))\ndef U(q,h,t,z):return D(c)[2*q+(h in t)]%3,h+1-2*q,t,z*1j*(1-2*q)\ndef R(s,x,b):\n j={};st=[]\n for i,z in enumerate(s):\n  if z=="[":st.append(i)\n  elif z=="]":a=st.pop();j[a]=i;j[i]=a\n  elif z not in A:raise ValueError\n if st:raise ValueError\n t={};h=i=k=u=0;o=bytearray()\n while i<len(s)and k<b:\n  z=s[i];v=t.get(h,0)\n  if z in "><":h+=ord(z)-61\n  elif z in "+-":t[h]=(v+44-ord(z))%256\n  elif z==".":o.append(v)\n  elif z==",":t[h]=x[u]if u<len(x)else 0;u+=1\n  elif z=="["and not v or z=="]"and v:i=j[i]\n  i+=1;k+=1\n return dict(status="HALTED"if i==len(s)else"BOUNDED",steps=k,hex=o.hex(),tape={str(a):v for a,v in t.items()if v})\ndef E(d):\n m=d["map"];w=d.get("weights",[1]*len(m));n=d.get("next")\n assert m and len(w)==len(m)and min(w)>0\n def H(v):\n  t=sum(v)\n  return -sum(p/t*math.log2(p/t)for p in v)\n g={}\n for a,v in zip(m,w):g[a]=g.get(a,0)+v\n if n!=None and(n<len(g)or n%1):raise ValueError\n y=H(w)\n return dict(entropy_bits=y,loss_bits=y-H(g.values()),eta=math.log(n/len(m))if n else None)\na=sys.argv[1:];cmd=(a or["check"])[0]\nif cmd=="check":r=dict(G257=D(G(b"abc"))==b"abc",U2=all(U(*U(q,h,(0,),1))==(q,h,(0,),1)for q in(0,1)for h in(0,1)),BF=R(",.",b"A",4)["hex"]=="41",ATGC=W("AGTC"*4)==b"U")\nelif cmd in("run8","run257","runatgc"):\n s=N(int(a[1]))if cmd=="run8"else(D(int(a[1],0))if cmd=="run257"else W(a[1])).decode()\n r=R(s,((a[2:]or[""])[0]).encode(),int((a[3:]or[10000])[0]))\nelif cmd=="encode":r=dict(g257=hex(G(a[1].encode())))\nelif cmd=="entropy":r=E(json.loads(a[1]))\nelse:r={}\nprint(json.dumps(r))' "$@"
